using System;
using System.Text;

namespace TCPipeAutoDraw.UI.Studio
{
    /// <summary>
    /// 工程量动态看板共享页面组件。工作台内嵌页和后续独立页均应直接复用本组件。
    /// </summary>
    internal static class CDBoxStudioQuantityDashboardPage
    {
        private const string ComponentScriptBase64 = "";
        private const string StylesBase64 = "";

        public static string BuildEmbeddedSection()
        {
            return "<section id=\"quantityDashboardPage\" style=\"display:none\"></section>";
        }

        public static string BuildStyles(bool standalone)
        {
            string css = Encoding.UTF8.GetString(Convert.FromBase64String(StylesBase64));
            if (!standalone) return css;
            return @"
:root{--bg:#f5f7fb;--panel:#fff;--panel2:#f8fafc;--muted:#64748b;--text:#162033;--line:#dce8f6;--brand:#3b82f6;--brand2:#7c3aed}
*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:var(--bg);color:var(--text);font-family:'Microsoft YaHei UI','Segoe UI',sans-serif}
" + css;
        }

        public static string BuildComponentScript()
        {
            return Encoding.UTF8.GetString(Convert.FromBase64String(ComponentScriptBase64));
        }
    }
}
